-- EVT hook file for personal_plate_menu (VRFW_Host handlers, docs/framework/lua-hosts.md). Graft character_reforged_board (plate_create_moves_hooks.lua). Generated by research/scripts/menu_assemble.py; do not edit by hand.
-- Character Reforged › the plate's move rows during the partner's move step of the aura mods' «Crear …» bank
-- (bank_create_moves_hooks.lua). The retail plate starts its move-order drag on a decide over a move row (a mouse click
-- or Aceptar: OnEnter / OnDecideFocus -> OnEnterCommon lifts the row). While the bank's move step is on (parameter
-- character_reforged_create_pick_moves), a decide on a move row is the pick instead: the row goes to the bank
-- (character_reforged_create_pick_row = row + 1) and the drag never starts; a held row, if any, is put back first.
-- When the bank gives back the team dock's plate it sends the empty card (chara 0) with
-- character_reforged_create_plate_release set: the plate forgets the bank's card and shows the dock's focused member
-- again (its pages otherwise kept the last bank card for every member).
-- HOOK file (graft [[hooks]], shipped as is): VRFW_Host handlers on the VR-Framework's host of this script. Definitions
-- only at chunk load (no engine call).
do
  CharacterReforged_PlateMoves = CharacterReforged_PlateMoves or {}
  local P = CharacterReforged_PlateMoves
  P.STEM = "personal_plate_menu"
  P.ID = "character_reforged.create_plate_moves"
  P.KEY_PICKING = 2195309509                         -- character_reforged_create_pick_moves
  P.KEY_PICKED_ROW = 2315084405                      -- character_reforged_create_pick_row
  P.SKILL_ROWS = 1580043721                          -- soccer11_09_formation_chara_skill (the plate's move rows)
  P.KEY_PLATE_RELEASE = 2526449858                   -- character_reforged_create_plate_release
  P.PARAM_HAS = 2947612279
  P.PARAM_DELETE = 3363400568
  P.PARAM_SET = 3860611758

  function P.Picking()
    return funcLuaCommand(P.PARAM_HAS, P.KEY_PICKING) == true
  end

  function P.Decide(nxt, layer, index, ...)
    if layer ~= P.SKILL_ROWS or not P.Picking() then
      return nxt(layer, index, ...)
    end
    -- a row held by the retail drag goes back to its place at once (no animation wait)
    if type(TerminateCharaSkillSort) == "function" then
      pcall(TerminateCharaSkillSort, true)
    end
    funcLuaCommand(P.PARAM_DELETE, P.KEY_PICKED_ROW)
    if type(index) == "number" and index >= 0 then
      funcLuaCommand(P.PARAM_SET, P.KEY_PICKED_ROW, 0, index + 1, 1)
    end
    return 1
  end

  -- the bank's card off the plate (UpdateCharaStHdlPersonalPlateFromCharaBank(0, ...) from the releasing bank)
  function P.Release(nxt, hdl, ...)
    if hdl ~= 0 or funcLuaCommand(P.PARAM_HAS, P.KEY_PLATE_RELEASE) ~= true then
      return nxt(hdl, ...)
    end
    funcLuaCommand(P.PARAM_DELETE, P.KEY_PLATE_RELEASE)
    if type(TerminateCharaSkillSort) == "function" then
      pcall(TerminateCharaSkillSort, true)
    end
    SetCharaStHdl(0, true)
    pcall(UpdatePersonalPlatePage)
  end

  if VRFW_Host ~= nil then
    VRFW_Host.on(P.STEM, "UpdateCharaStHdlPersonalPlateFromCharaBank", {id = P.ID .. ".release", phase = "around",
      fn = function(nxt, ...)
        return P.Release(nxt, ...)
      end})
    for _, point in ipairs({"OnEnter", "OnDecideFocus"}) do
      VRFW_Host.on(P.STEM, point, {id = P.ID .. ".pick", phase = "around", fn = function(nxt, ...)
        return P.Decide(nxt, ...)
      end})
    end
  end
end
